import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.CjAa9jTu.js";const m=JSON.parse('{"title":"Imágenes y recursos del PY32F003","description":"","frontmatter":{},"headers":[],"relativePath":"py32f003-getting-started/recursos.md","filePath":"py32f003-getting-started/recursos.md"}'),s={name:"py32f003-getting-started/recursos.md"};function n(i,e,l,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="imagenes-y-recursos-del-py32f003" tabindex="-1">Imágenes y recursos del PY32F003 <a class="header-anchor" href="#imagenes-y-recursos-del-py32f003" aria-label="Permalink to &quot;Imágenes y recursos del PY32F003&quot;">​</a></h1><h2 id="documentacion-para-el-taller" tabindex="-1">Documentación para el taller <a class="header-anchor" href="#documentacion-para-el-taller" aria-label="Permalink to &quot;Documentación para el taller&quot;">​</a></h2><p>Estos recursos se copiaron del repositorio <strong>Development Board</strong> al sitio de Cortex para que las imágenes y descargas estén disponibles desde la misma documentación. Las figuras originales conservan las etiquetas de su autor; el pinout tiene versión en español.</p><table tabindex="0"><thead><tr><th>Recurso</th><th>Archivo</th></tr></thead><tbody><tr><td>Pinout en español</td><td><a href="/unit_devlab_cortex_m_examples/py32f003/pinout-es.pdf">PDF</a> · <a href="/unit_devlab_cortex_m_examples/py32f003/pinout-es.png">PNG</a></td></tr><tr><td>Esquemático de la placa</td><td><a href="/unit_devlab_cortex_m_examples/py32f003/esquematico.pdf">PDF</a></td></tr><tr><td>Hoja de datos PY32F003, revisión 1.7</td><td><a href="/unit_devlab_cortex_m_examples/py32f003/PY32F003_Datasheet_Rev1.7.pdf">PDF del fabricante, en inglés</a></td></tr><tr><td>Manual original de la placa</td><td><a href="/unit_devlab_cortex_m_examples/py32f003/manual-placa-en.pdf">PDF, en inglés</a></td></tr><tr><td>Vista superior</td><td><a href="/unit_devlab_cortex_m_examples/py32f003/placa-superior.png">PNG</a></td></tr><tr><td>Vista inferior</td><td><a href="/unit_devlab_cortex_m_examples/py32f003/placa-inferior.png">PNG</a></td></tr><tr><td>Topología</td><td><a href="/unit_devlab_cortex_m_examples/py32f003/topologia.png">PNG</a></td></tr><tr><td>Dimensiones</td><td><a href="/unit_devlab_cortex_m_examples/py32f003/dimensiones.png">PNG</a></td></tr><tr><td>Conexión del programador</td><td><a href="/unit_devlab_cortex_m_examples/py32f003/conexion-swd.jpeg">Fotografía</a></td></tr><tr><td>Ejemplos de Arduino</td><td><a href="/unit_devlab_cortex_m_examples/examples/py32f003-ejemplos.zip">ZIP</a></td></tr><tr><td>Registro de validación</td><td><a href="/unit_devlab_cortex_m_examples/examples/registro-validacion.csv">CSV</a></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Cómo interpretar las referencias</p><p>El manual original contiene diferencias entre tablas y descripciones de la familia. Esta guía utiliza la columna <strong>PY32F003L24D6</strong> de la tabla 1-4 de la hoja de datos: Cortex-M0+, <strong>16 KB de Flash, 2 KB de RAM y 24 MHz</strong>. Las opciones de Arduino se documentan para el paquete <strong>0.1.7</strong>.</p></div><h2 id="procedencia" tabindex="-1">Procedencia <a class="header-anchor" href="#procedencia" aria-label="Permalink to &quot;Procedencia&quot;">​</a></h2><ul><li>Hardware y figuras: <a href="https://github.com/UNIT-Electronics-MX/unit_devlab_py32f003l24d6tr_development_board" target="_blank" rel="noreferrer">DevLab PY32F003L24D6TR Development Board</a>.</li><li>Capturas y ejemplos de referencia: <code>software/sphinx/src/source/</code> del mismo repositorio.</li><li><a href="/unit_devlab_cortex_m_examples/py32f003/procedencia.json">Correspondencia de nombres locales y rutas originales (JSON)</a>.</li><li>Entorno de programación: <a href="https://github.com/UNIT-Electronics-MX/unit_electronics_py32_arduino_package" target="_blank" rel="noreferrer">paquete Arduino de UNIT Electronics</a>.</li><li>Programación y permisos USB: <a href="https://pyocd.io/docs/installing.html" target="_blank" rel="noreferrer">documentación de pyOCD</a>.</li></ul><p>Los ejemplos iniciales adaptan las prácticas de Blink, UART y ADC a un recorrido de taller en español. Las imágenes y documentos conservan su autoría original de UNIT Electronics y Puya Semiconductor, según corresponda.</p><h2 id="descarga-para-trabajar-localmente" tabindex="-1">Descarga para trabajar localmente <a class="header-anchor" href="#descarga-para-trabajar-localmente" aria-label="Permalink to &quot;Descarga para trabajar localmente&quot;">​</a></h2><p>Descarga el ZIP de ejemplos, el pinout y el esquemático antes de la sesión. Las capturas de Arduino se utilizan como apoyo; sigue los valores escritos en la <a href="./02_0_duino#_3-seleccionar-la-placa-y-sus-opciones">tabla de configuración</a>.</p>',10)])])}const _=a(s,[["render",n]]);export{m as __pageData,_ as default};
